// SPDX-License-Identifier: AGPL-3.0-only
// Generates the host-neutral Agent Skills set (plugin-agents/skills/**) that the
// Wenlan app installs into other AI tools (Cursor, GitHub Copilot, VS Code,
// Windsurf, Antigravity, Kiro, OpenCode, Gemini CLI) from the hand-written
// Claude skills plus plugin-agents/overlay.json, and the Rust bundle
// app/src/agent_skills_bundle.rs that embeds every generated file.
//
// It reuses the Codex generator's section/replace/frontmatter helpers
// (scripts/gen-codex-plugin.mjs) and the same plugin-contract.json inventory:
// a `shared_now` skill becomes plugin-agents/skills/<folder>/SKILL.md, a
// `hidden_routed` skill becomes the reference file
// plugin-agents/skills/wenlan/references/<skill>.md, which the `wenlan` front
// door reads. The Claude file is the only hand-written prose; the overlay
// carries the structural differences (sections or line runs a host-neutral
// skill replaces or drops, and an optional description override).
//
// Output tree:
//   wenlan/SKILL.md                 front door
//   wenlan/references/<workflow>.md routed workflows (setup, distill, steep, ...)
//   wenlan/scripts/resolve-space.sh copied from plugin/scripts (installer sets 0755)
//   wenlan-brief|capture|recall|handoff/SKILL.md
//
// Pipeline per skill, in order:
//   1. overlay `sections`  : heading -> replacement lines, or null to drop
//   2. overlay `replace`   : exact contiguous line runs -> replacement, or null
//   3. frontmatter         : keep only `name` (prefixed to match the folder) and
//                            `description` (folded onto one quoted line); drop
//                            allowed-tools, argument-hint, user-invocable, which
//                            are not part of the open Agent Skills format. A
//                            reference drops the frontmatter.
//   4. resolver path       : "${CLAUDE_PLUGIN_ROOT}/scripts/resolve-space.sh" ->
//                            "{{WENLAN_SKILLS_DIR}}/wenlan/scripts/resolve-space.sh"
//                            (the installer substitutes the absolute skills folder)
//   5. MCP tool names      : mcp__plugin_wenlan_wenlan__<tool>( -> <tool>( and
//                            `mcp__plugin_wenlan_wenlan__<tool>` -> the Wenlan `<tool>` tool
//   6. skill invocations   : /wenlan:<skill> and bare /<skill> -> /wenlan-<skill>
//   7. leftover guard      : fail on any Claude/Codex-only token, a resolver path
//                            without the placeholder, an invalid name or an
//                            over-long description
//
// `--check` exits 1 when a generated file differs or a file under
// plugin-agents/skills is generated by nothing; `--root <dir>` points at another
// tree.
import { createHash } from "node:crypto";
import { chmodSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import {
  GenError,
  applyReplace,
  applySections,
  checkHiddenFrontmatter,
  fail,
  parseFrontmatter,
  pruneEmptyDirs,
  splitFrontmatter,
  strayFiles,
} from "./gen-codex-plugin.mjs";

export const OVERLAY_PATH = "plugin-agents/overlay.json";
export const CONTRACT_PATH = "plugin-contract.json";
export const OUT_ROOT = "plugin-agents";
export const BUNDLE_PATH = "app/src/agent_skills_bundle.rs";
const RESOLVER_SOURCE = "plugin/scripts/resolve-space.sh";
const RESOLVER_OUT = "wenlan/scripts/resolve-space.sh";
export const SKILLS_DIR_PLACEHOLDER = "{{WENLAN_SKILLS_DIR}}";
const FRONT_DOOR = "wenlan";
const DESCRIPTION_MAX = 1024;
const NAME_MAX = 64;

const CLAUDE_RESOLVER = "${CLAUDE_PLUGIN_ROOT}/scripts/resolve-space.sh";
const AGENT_RESOLVER = `${SKILLS_DIR_PLACEHOLDER}/${RESOLVER_OUT}`;

// Any of these in a generated skill means the overlay or a swap rule missed a
// Claude- or Codex-only detail.
const LEFTOVER_TOKENS = [
  "CLAUDE_PLUGIN_ROOT",
  ".claude-plugin",
  "AskUserQuestion",
  "claude-code",
  "Claude",
  "Codex",
  "CODEX_",
  "$wenlan",
  "mcp__",
  "/wenlan:",
  "/plugin ",
  "npx -y wenlan@",
  "version-drift",
  "plugin.json",
  "allowed-tools",
  "user-invocable",
  "Skill tool",
  "`Agent`",
  "Bash",
];

// --- naming ----------------------------------------------------------------

// `wenlan` keeps its name; every other shared skill is prefixed so it cannot
// clash with another tool's skill in a shared folder.
export const agentName = (skill) => (skill === FRONT_DOOR ? FRONT_DOOR : `${FRONT_DOOR}-${skill}`);

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// --- frontmatter -----------------------------------------------------------

// The description as one string. A folded (`>`) block joins its lines with a
// single space; a plain single-line value is taken as is.
function descriptionText(skill, fields, overlay) {
  if (overlay.description !== undefined) {
    if (!Array.isArray(overlay.description) || overlay.description.length === 0) {
      fail(skill, "overlay description must be a non-empty array of lines");
    }
    return overlay.description.map((l) => l.trim()).join(" ");
  }
  const d = fields.find((f) => f.key === "description");
  if (!d) fail(skill, "SKILL.md needs a description");
  const [head, ...rest] = d.value;
  if (head === ">") return rest.map((l) => l.trim()).filter(Boolean).join(" ");
  if (head === "" || head.startsWith("|") || head.startsWith(">") || rest.length) {
    fail(skill, "description must be a single-line value or a folded (>) block");
  }
  return head.trim();
}

function transformFrontmatter(skill, lines, overlay) {
  const fields = parseFrontmatter(skill, lines);
  const byKey = (k) => fields.find((f) => f.key === k);
  if (byKey("name")?.value[0] !== skill) fail(skill, "frontmatter name mismatch");
  if (byKey("user-invocable")) fail(skill, "a shared Claude skill must not set user-invocable");
  const description = descriptionText(skill, fields, overlay);
  // JSON strings are valid YAML double-quoted scalars, and a single quoted line
  // is read the same by every host's frontmatter parser.
  return [`name: ${agentName(skill)}`, `description: ${JSON.stringify(description)}`];
}

// --- body transforms -------------------------------------------------------

function swapResolver(text) {
  return text.replaceAll(CLAUDE_RESOLVER, AGENT_RESOLVER);
}

// Claude names every MCP tool with the plugin's server prefix. The server is
// called `wenlan` in every host, so skill text names the tool itself: in a call
// (`tool(`) bare, in prose as "the Wenlan `tool` tool".
function neutralTools(text, claudePrefix) {
  const p = escapeRe(claudePrefix);
  return text
    .replace(new RegExp(`${p}(\\w+)(?=\\()`, "g"), "$1")
    .replace(new RegExp(`\`${p}(\\w+)\``, "g"), "the Wenlan `$1` tool");
}

// Hosts list a skill under its folder name, so `/brief` becomes
// `/wenlan-brief`. `/wenlan` (the front door) and paths such as `~/.wenlan/`
// are left alone.
function swapSkillCommands(text, prefixed) {
  const names = prefixed.map(escapeRe).join("|");
  return text
    .replace(new RegExp(`/wenlan:(${names})(?![\\w-])`, "g"), "/wenlan-$1")
    .replace(new RegExp(`(?<![\\w.~/$-])/(${names})(?![\\w/:-]|\\.\\w)`, "g"), "/wenlan-$1");
}

function guardLeftovers(skill, text, isSkill) {
  for (const token of LEFTOVER_TOKENS) {
    if (text.includes(token)) {
      const line = text.split("\n").findIndex((l) => l.includes(token)) + 1;
      fail(skill, `generated file still contains ${JSON.stringify(token)} (line ${line}); add an overlay replace for it`);
    }
  }
  const lines = text.split("\n");
  lines.forEach((l, i) => {
    if (l.includes("/resolve-space.sh") && !l.includes(AGENT_RESOLVER)) {
      fail(skill, `line ${i + 1} names a resolve-space.sh path without ${AGENT_RESOLVER}`);
    }
  });
  if (isSkill) {
    const m = text.match(/^---\nname: (.+)\ndescription: (".*")\n---\n/);
    if (!m) fail(skill, "frontmatter must be exactly name and description");
    if (m[1] !== agentName(skill) || m[1].length > NAME_MAX || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(m[1])) {
      fail(skill, `name ${JSON.stringify(m[1])} is not a valid Agent Skills name`);
    }
    const description = JSON.parse(m[2]);
    if (description.length > DESCRIPTION_MAX) {
      fail(skill, `description is ${description.length} characters; the limit is ${DESCRIPTION_MAX}`);
    }
  }
}

function transformBody(skill, body, overlay) {
  let lines = body;
  if (overlay.sections) lines = applySections(skill, lines, overlay.sections);
  if (overlay.replace) lines = applyReplace(skill, lines, overlay.replace);
  return lines;
}

function finish(skill, text, contract, prefixed, isSkill) {
  let out = swapResolver(text);
  out = neutralTools(out, contract.surfaces.claude.skill_mcp_tool_prefix);
  out = swapSkillCommands(out, prefixed);
  guardLeftovers(skill, out, isSkill);
  return out;
}

const prefixedSkills = (contract) =>
  contract.skills
    .filter((s) => s.status === "shared_now" && s.name !== FRONT_DOOR)
    .map((s) => s.name);

// A shared skill: frontmatter (name, description) plus the transformed body.
export function generateSkill(skill, claudeText, overlay, contract) {
  const { frontmatter, body } = splitFrontmatter(skill, claudeText);
  const lines = transformBody(skill, body, overlay);
  const fm = transformFrontmatter(skill, frontmatter, overlay);
  return finish(skill, ["---", ...fm, "---", ...lines].join("\n"), contract, prefixedSkills(contract), true);
}

// A hidden_routed skill becomes a plain reference file: the Claude body with
// the same transforms and no frontmatter.
export function generateReference(skill, claudeText, overlay, contract) {
  if (overlay.description !== undefined) {
    fail(skill, "a hidden_routed skill is a reference file; drop its overlay description");
  }
  const { frontmatter, body } = splitFrontmatter(skill, claudeText);
  checkHiddenFrontmatter(skill, frontmatter);
  let lines = transformBody(skill, body, overlay);
  while (lines.length && lines[0] === "") lines = lines.slice(1);
  return finish(skill, lines.join("\n"), contract, prefixedSkills(contract), false);
}

// --- Rust bundle -----------------------------------------------------------

// First 16 hex digits of sha256 over every file's path and contents, in path
// order. Paths are relative to the skills folder.
export function bundleVersion(files) {
  const hash = createHash("sha256");
  for (const { path, text } of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) {
    hash.update(`${path}\0${text}\0`);
  }
  return hash.digest("hex").slice(0, 16);
}

// Written the way rustfmt writes it, so `cargo fmt --check` accepts the file.
export function renderBundle(files) {
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : 1));
  const entries = sorted.map(
    ({ path }) =>
      `    (\n        ${JSON.stringify(path)},\n        include_str!(${JSON.stringify(`../../${OUT_ROOT}/skills/${path}`)}),\n    ),\n`,
  );
  return [
    "// SPDX-License-Identifier: AGPL-3.0-only",
    "//! Wenlan's Agent Skills bundle for other AI tools (Cursor, GitHub Copilot,",
    "//! VS Code, Windsurf, Antigravity, Kiro, OpenCode, Gemini CLI).",
    "//!",
    "//! Generated by `scripts/gen-agent-skills.mjs` from `plugin/skills` and",
    "//! `plugin-agents/overlay.json`; do not edit. Regenerate with",
    "//! `node scripts/gen-agent-skills.mjs`. CI runs it with `--check`.",
    "//!",
    `//! Text files may contain the placeholder \`${SKILLS_DIR_PLACEHOLDER}\`, which the`,
    "//! installer replaces with the absolute path of the skills folder it installs",
    "//! into. `wenlan/scripts/resolve-space.sh` must be installed executable (0755).",
    "",
    "/// First 16 hex digits of the SHA-256 over every file's path and contents in",
    "/// `FILES`, sorted by path. Changes whenever any installed skill changes.",
    `pub const BUNDLE_VERSION: &str = ${JSON.stringify(bundleVersion(files))};`,
    "",
    "/// Every file of the bundle as (path relative to the skills folder, contents),",
    "/// sorted by path.",
    "pub const FILES: &[(&str, &str)] = &[",
    ...entries.map((e) => e.replace(/\n$/, "")),
    "];",
    "",
  ].join("\n");
}

// --- driver ----------------------------------------------------------------

// The Claude setup skill pins `npx -y wenlan@X.Y.Z setup`, and the release bump
// rewrites that pin without knowing this overlay. An overlay `from` run writes
// the pin as VERSION_TOKEN, read from the Claude plugin manifest, so a release
// needs no edit here.
export const VERSION_TOKEN = "{{plugin_version}}";

function withPluginVersion(root, claudeRoot, overlayText) {
  if (!overlayText.includes(VERSION_TOKEN)) return overlayText;
  const manifest = `${claudeRoot}/.claude-plugin/plugin.json`;
  const { version } = JSON.parse(readFileSync(resolve(root, manifest), "utf8"));
  if (typeof version !== "string" || !/^[0-9A-Za-z.+-]+$/.test(version)) {
    throw new GenError(`${manifest}: version must be a plain version string`);
  }
  return overlayText.replaceAll(VERSION_TOKEN, version);
}

export function generateAll(root) {
  const contract = JSON.parse(readFileSync(resolve(root, CONTRACT_PATH), "utf8"));
  const claudeRoot = contract.surfaces.claude.plugin_root;
  const overlayAll = JSON.parse(withPluginVersion(root, claudeRoot, readFileSync(resolve(root, OVERLAY_PATH), "utf8")));
  const shared = contract.skills.filter((s) => s.status === "shared_now").map((s) => s.name);
  const hidden = contract.skills.filter((s) => s.status === "hidden_routed").map((s) => s.name);
  if (!shared.includes(FRONT_DOOR)) throw new GenError(`${CONTRACT_PATH}: the ${FRONT_DOOR} front door must be a shared_now skill`);
  const known = [...shared, ...hidden];
  const unknown = Object.keys(overlayAll.skills ?? {}).filter((s) => !known.includes(s));
  if (unknown.length) throw new GenError(`${OVERLAY_PATH} names skills not generated from ${CONTRACT_PATH}: ${unknown.join(", ")}`);

  const source = (skill) => readFileSync(resolve(root, claudeRoot, "skills", skill, "SKILL.md"), "utf8");
  const files = [];
  for (const skill of shared) {
    files.push({
      path: `${agentName(skill)}/SKILL.md`,
      text: generateSkill(skill, source(skill), overlayAll.skills?.[skill] ?? {}, contract),
    });
  }
  for (const skill of hidden) {
    files.push({
      path: `${FRONT_DOOR}/references/${skill}.md`,
      text: generateReference(skill, source(skill), overlayAll.skills?.[skill] ?? {}, contract),
    });
  }
  files.push({
    path: RESOLVER_OUT,
    text: readFileSync(resolve(root, RESOLVER_SOURCE), "utf8"),
    mode: 0o755,
  });

  const outputs = files.map((f) => ({ ...f, path: `${OUT_ROOT}/skills/${f.path}`, rel: f.path }));
  outputs.push({ path: BUNDLE_PATH, text: renderBundle(files) });
  return outputs;
}

function diffHint(path, actual, expected) {
  const a = actual.split("\n");
  const e = expected.split("\n");
  const out = [`${path} is out of date with the Claude skills + ${OVERLAY_PATH}:`];
  for (let i = 0; i < Math.max(a.length, e.length); i++) {
    if (a[i] === e[i]) continue;
    out.push(`  line ${i + 1}:`, `  - ${a[i] ?? "<missing>"}`, `  + ${e[i] ?? "<missing>"}`);
    if (out.length > 13) {
      out.push("  ...");
      break;
    }
  }
  return out.join("\n");
}

function rootValue(argv, idx) {
  const value = argv[idx + 1];
  if (value === undefined || value.startsWith("--")) {
    console.error("usage: gen-agent-skills.mjs [--check] [--root <dir>]");
    process.exit(64);
  }
  return value;
}

function main() {
  const args = process.argv.slice(2);
  const check = args.includes("--check");
  const rootIdx = args.indexOf("--root");
  const root =
    rootIdx >= 0
      ? resolve(rootValue(args, rootIdx))
      : resolve(dirname(fileURLToPath(import.meta.url)), "..");

  let outputs;
  try {
    outputs = generateAll(root);
  } catch (err) {
    if (err instanceof GenError) {
      console.error(`gen-agent-skills: ${err.message}`);
      process.exit(2);
    }
    throw err;
  }

  let stale = 0;
  for (const { path, text, mode } of outputs) {
    const file = resolve(root, path);
    const actual = existsSync(file) ? readFileSync(file, "utf8") : "";
    if (actual === text) continue;
    if (check) {
      stale++;
      console.error(diffHint(path, actual, text));
    } else {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, text);
      if (mode) chmodSync(file, mode);
      console.log(`updated ${path}`);
    }
  }
  for (const path of strayFiles(root, outputs, OUT_ROOT)) {
    if (check) {
      stale++;
      console.error(`${path} is not generated by any skill; delete it`);
    } else {
      rmSync(resolve(root, path));
      console.log(`deleted ${path}`);
    }
  }
  const skillsDir = resolve(root, OUT_ROOT, "skills");
  if (!check && existsSync(skillsDir)) {
    for (const e of readdirSync(skillsDir, { withFileTypes: true })) {
      if (e.isDirectory()) pruneEmptyDirs(resolve(skillsDir, e.name));
    }
  }
  if (stale) {
    console.error("run: node scripts/gen-agent-skills.mjs");
    process.exit(1);
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
